package com.estradaplay.patriota;
import android.content.Context;import org.json.*;import java.util.*;
final class FavoriteRoadStore{private static final String P="epp_road_favorites_v160",K="rows";static final class Item{final String name,type;final double lat,lon;Item(String n,String t,double a,double b){name=n==null?"Ponto":n;type=t==null?"":t;lat=a;lon=b;}}static void add(Context c,Item x){if(x==null)return;try{JSONArray old=raw(c),out=new JSONArray();JSONObject n=new JSONObject();n.put("name",x.name);n.put("type",x.type);n.put("lat",x.lat);n.put("lon",x.lon);out.put(n);for(int i=0;i<old.length()&&out.length()<50;i++){JSONObject o=old.optJSONObject(i);if(o==null)continue;if(Math.abs(o.optDouble("lat")-x.lat)<.00001&&Math.abs(o.optDouble("lon")-x.lon)<.00001)continue;out.put(o);}c.getSharedPreferences(P,Context.MODE_PRIVATE).edit().putString(K,out.toString()).apply();}catch(Throwable ignored){}}static ArrayList<Item> list(Context c){ArrayList<Item> out=new ArrayList<>();JSONArray a=raw(c);for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null)out.add(new Item(o.optString("name"),o.optString("type"),o.optDouble("lat"),o.optDouble("lon")));}return out;}static void remove(Context c,double lat,double lon){JSONArray a=raw(c),out=new JSONArray();for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;if(Math.abs(o.optDouble("lat")-lat)<.00001&&Math.abs(o.optDouble("lon")-lon)<.00001)continue;out.put(o);}c.getSharedPreferences(P,Context.MODE_PRIVATE).edit().putString(K,out.toString()).apply();}private static JSONArray raw(Context c){try{return new JSONArray(c.getSharedPreferences(P,Context.MODE_PRIVATE).getString(K,"[]"));}catch(Throwable e){return new JSONArray();}}}
